(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-719":{scenario:{company:"Truong Xuan General Hospital",supervisor:{name:"Châu Ngọc Diệp",role:{vi:"Trưởng bộ phận Bảo hiểm y tế",en:"Health Insurance Unit Lead"}},ref_code:"BH-6382",title:{vi:"Đúng mã bệnh. Đúng phạm vi chi trả. Không trục lợi.",en:"Right code. Right coverage. No fraud."},brief:{vi:"Đây là tình huống đào tạo. Bạn giám định hồ sơ ra viện BH-6382 của người bệnh nội trú, chẩn đoán đái tháo đường týp 2 có bệnh thận do đái tháo đường, đang điều trị insulin. Tổng chi phí điều trị 9.240.000 đồng, trong đó 740.000 đồng là thuốc ngoài danh mục BHYT; thẻ có mức hưởng 80% (số liệu mô phỏng), khám chữa bệnh đúng tuyến. Đối chiếu bảng kê nháp với hồ sơ bệnh án, sửa mã ICD-10 bệnh chính và số tiền BHYT chi trả, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You audit discharge claim BH-6382 for an inpatient with type 2 diabetes and diabetic kidney disease, treated with insulin. Total treatment cost is 9,240,000 VND, of which 740,000 VND is a drug outside the insurance formulary; the card's benefit level is 80% (simulated figure) and care was at the correct facility level. Compare the draft claim with the medical record, correct the principal ICD-10 code and the insurer-paid amount, then write an evidence-based report."},reference_title:{vi:"Hồ sơ bệnh án & bảng kê chi phí gốc",en:"Medical record & original cost statement"},fields:[{id:"ICD_MAIN",label:{vi:"Mã ICD-10 bệnh chính",en:"Principal ICD-10 code"},initial:"E11.9",expected:"E11.2",choices:["E10.2","E11.2","E11.9"],reference:"Tóm tắt bệnh án ra viện",ref_value:{vi:"Đái tháo đường týp 2 có biến chứng thận (bệnh thận do đái tháo đường); dùng insulin không đổi týp bệnh",en:"Type 2 diabetes with renal complications (diabetic kidney disease); insulin use does not change the type"},hint:{vi:"Ký tự thứ tư của nhóm E11 thể hiện biến chứng; .9 chỉ dùng khi không có biến chứng.",en:"The fourth character in E11 shows the complication; .9 is only for no complications."}},{id:"BHYT_PAY",label:{vi:"Số tiền BHYT chi trả (VND)",en:"Insurer-paid amount (VND)"},initial:"7392000",expected:"6800000",reference:"Bảng kê chi phí gốc",ref_value:{vi:"Tổng chi phí 9.240.000 đồng; ngoài danh mục BHYT 740.000 đồng; mức hưởng 80% (mô phỏng)",en:"Total cost 9,240,000 VND; outside formulary 740,000 VND; benefit level 80% (simulated)"},hint:{vi:"Chi phí ngoài danh mục không thuộc phạm vi thanh toán BHYT, phải loại trước khi áp mức hưởng.",en:"Out-of-formulary costs are not covered and must be removed before applying the benefit level."}}],sop32:{vi:"Phần BHYT chi trả = (tổng chi phí - chi phí ngoài phạm vi, danh mục BHYT) x mức hưởng ghi trên thẻ (bài mô phỏng 80%). Phần ngoài danh mục và phần cùng chi trả do người bệnh thanh toán.",en:"Insurer-paid amount = (total cost - costs outside insurance coverage or formulary) x the card benefit level (simulated 80%). Out-of-formulary costs and the co-payment are paid by the patient."},context:{label:"HIS / BH-6382",metrics:[{label:{vi:"Tổng chi phí",en:"Total cost"},value:"9,240,000 VND"},{label:{vi:"Ngoài danh mục BHYT",en:"Outside formulary"},value:"740,000 VND"},{label:{vi:"Mức hưởng mô phỏng",en:"Simulated benefit level"},value:"80%"},{label:{vi:"Hạn gửi dữ liệu hôm nay",en:"Claim data deadline today"},value:"17:00"}]},crisis:{vi:"Trưởng khoa Nội nhắn: “Thêm mã suy thận mạn giai đoạn cuối và kê thêm 2 lần lọc máu vào bảng kê để bù phần vượt trần của khoa. Bên giám định không kiểm được đâu, chiều nay gửi luôn.”",en:"The Head of Internal Medicine messages you: “Add an end-stage kidney disease code and two dialysis sessions to the claim to cover the ward's budget overrun. The auditors will never check, send it this afternoon.”"},options:{safe:{vi:"Từ chối kê khống và nâng mã, mã hóa đúng theo bệnh án, gửi phiếu đề nghị bác sĩ xác nhận nếu hồ sơ thiếu thông tin, báo Trưởng phòng Kế hoạch tổng hợp và giải trình vượt trần theo quy trình hợp lệ.",en:"Refuse phantom services and upcoding, code strictly from the record, send the doctor a written query if documentation is missing, inform the Head of General Planning and explain the overrun properly."},shortcut:{vi:"Thêm mã suy thận giai đoạn cuối và 2 lần lọc máu rồi gửi dữ liệu cho kịp hạn.",en:"Add the end-stage code and two dialysis sessions and submit before the deadline."},wait:{vi:"Không gửi hồ sơ và chờ trưởng khoa tự chỉnh bảng kê.",en:"Hold the claim and wait for the department head to edit it himself."}},questions:{vi:["Vì sao bệnh chính là E11.2 chứ không phải E11.9 hay E10.2, và số tiền BHYT chi trả đúng là 6.800.000 đồng?","Bạn xử lý yêu cầu thêm mã và dịch vụ không có thật thế nào, và trao đổi với bác sĩ khi hồ sơ ghi chép chưa đủ ra sao?"],en:["Why is the principal code E11.2 rather than E11.9 or E10.2, and why is the insurer-paid amount 6,800,000 VND?","How do you handle the request to add codes and services that did not happen, and how do you query the doctor when documentation is incomplete?"]},hints:{vi:["Đọc tóm tắt bệnh án: xác định týp đái tháo đường và biến chứng được ghi nhận.","Loại phần ngoài danh mục BHYT khỏi tổng chi phí trước khi nhân mức hưởng ở SOP mục 3.2.","Đọc lại SOP mục 4.2: không kê khống dịch vụ, không nâng mã; mọi áp lực phải báo người có thẩm quyền."],en:["Read the discharge summary: identify the diabetes type and the recorded complication.","Remove out-of-formulary costs from the total before applying the benefit level in SOP 3.2.","Re-read SOP 4.2: never bill unperformed services or upcode; escalate any pressure."]}},learning:{summary:{vi:"Chuyên viên giám định và thanh toán bảo hiểm y tế mã hóa chẩn đoán, thủ thuật theo ICD-10, kiểm tra bảng kê chi phí, đối chiếu phạm vi quyền lợi và gửi dữ liệu thanh toán cho cơ quan bảo hiểm. Người làm nghề bảo đảm cơ sở y tế được thanh toán đúng, đủ, kịp thời, người bệnh được hưởng đúng quyền lợi và quỹ bảo hiểm không bị trục lợi.",en:"A medical coding and health insurance claims specialist codes diagnoses and procedures with ICD-10, checks cost statements, verifies coverage and submits claim data to the insurer. The role makes sure the hospital is paid correctly and on time, patients receive their full entitlements and the insurance fund is protected from abuse."},responsibilities:{vi:["Đọc bệnh án, chọn bệnh chính, bệnh kèm theo và mã hóa theo ICD-10.","Kiểm tra bảng kê thuốc, vật tư, dịch vụ kỹ thuật theo danh mục và điều kiện thanh toán.","Xác định mức hưởng, phần cùng chi trả và phần người bệnh tự thanh toán.","Gửi dữ liệu điện tử theo chuẩn đầu ra, xử lý phản hồi và giải trình xuất toán.","Phối hợp với khoa lâm sàng cải thiện chất lượng ghi chép bệnh án."],en:["Read records, select principal and secondary diagnoses and code them in ICD-10.","Check drugs, supplies and procedures against the formulary and payment conditions.","Determine the benefit level, co-payment and patient-paid amounts.","Submit electronic data in the required format, handle feedback and contest disallowances.","Work with clinical wards to improve documentation quality."]},competencies:[{name:{vi:"Mã hóa lâm sàng",en:"Clinical coding"},desc:{vi:"Áp dụng quy tắc ICD-10 về chọn bệnh chính, ký tự thứ tư, mã dấu dao găm và dấu sao.",en:"Apply ICD-10 rules on principal diagnosis, fourth characters and dagger-asterisk codes."}},{name:{vi:"Nghiệp vụ BHYT",en:"Health insurance rules"},desc:{vi:"Nắm phạm vi quyền lợi, mức hưởng, danh mục thanh toán và điều kiện chi trả.",en:"Know coverage scope, benefit levels, the payment formulary and reimbursement conditions."}},{name:{vi:"Kiến thức y khoa nền",en:"Medical background"},desc:{vi:"Hiểu thuật ngữ y khoa, giải phẫu, bệnh học để đọc đúng bệnh án.",en:"Understand medical terminology, anatomy and pathology to read records correctly."}},{name:{vi:"Kiểm soát dữ liệu",en:"Data control"},desc:{vi:"Đối chiếu chéo bệnh án, chỉ định, bảng kê và dữ liệu điện tử trước khi gửi.",en:"Cross-check records, orders, statements and electronic data before submission."}},{name:{vi:"Chống trục lợi",en:"Fraud prevention"},desc:{vi:"Từ chối kê khống, nâng mã, tách dịch vụ; báo cáo dấu hiệu gian lận.",en:"Refuse phantom billing, upcoding and unbundling and report signs of fraud."}}],knowledge:{vi:["Luật Bảo hiểm y tế số 25/2008/QH12, sửa đổi bởi Luật 46/2014/QH13 và các lần sửa đổi sau.","Quy định hiện hành về phạm vi quyền lợi, mức hưởng và thanh toán chi phí khám chữa bệnh BHYT.","Bảng phân loại quốc tế bệnh tật ICD-10 của WHO và hướng dẫn mã hóa bệnh tật của Bộ Y tế.","Danh mục thuốc, vật tư y tế, dịch vụ kỹ thuật thuộc phạm vi thanh toán BHYT.","Chuẩn dữ liệu đầu ra phục vụ giám định, thanh toán chi phí khám chữa bệnh BHYT.","Các hình thức trục lợi: kê khống, nâng mã, tách dịch vụ và chế tài xử lý."],en:["Health Insurance Law No. 25/2008/QH12, amended by Law 46/2014/QH13 and later amendments.","Current rules on coverage, benefit levels and reimbursement of insured care.","The WHO ICD-10 classification and the Ministry of Health coding guidance.","Lists of drugs, medical supplies and procedures covered by health insurance.","The output data standard for insurance claim auditing and payment.","Forms of abuse: phantom billing, upcoding and unbundling, and their penalties."]},tools:["Hệ thống thông tin bệnh viện (HIS)","Công cụ tra cứu ICD-10","Hệ thống thông tin giám định BHYT","Phần mềm kiểm tra dữ liệu XML trước khi gửi","Microsoft Excel"],kpis:{vi:["Tỷ lệ hồ sơ bị xuất toán trên tổng số hồ sơ gửi giám định.","Độ chính xác mã hóa qua kiểm tra mẫu ngẫu nhiên.","Tỷ lệ dữ liệu gửi đúng hạn và đúng chuẩn.","Số phát hiện kê khống, nâng mã khi kiểm tra (mục tiêu bằng 0)."],en:["Share of claims disallowed out of all claims submitted.","Coding accuracy in random sample audits.","Share of data submitted on time and in the correct format.","Phantom billing or upcoding findings in audits (target zero)."]},day:[{time:"08:00",vi:"Nhận hồ sơ ra viện, kiểm tra thông tin thẻ và đúng tuyến.",en:"Receive discharge files and check card details and facility level."},{time:"09:30",vi:"Đọc bệnh án, chọn bệnh chính, bệnh kèm theo và mã hóa ICD-10.",en:"Read records, choose principal and secondary diagnoses and code in ICD-10."},{time:"11:00",vi:"Đối chiếu bảng kê với chỉ định, danh mục và loại chi phí ngoài phạm vi.",en:"Match statements with orders and the formulary and remove uncovered costs."},{time:"14:00",vi:"Gửi phiếu đề nghị bác sĩ làm rõ chẩn đoán khi ghi chép chưa đủ.",en:"Send queries to doctors when diagnoses are poorly documented."},{time:"16:00",vi:"Kiểm tra lỗi dữ liệu XML, gửi giám định và xử lý phản hồi xuất toán.",en:"Validate XML data, submit claims and handle disallowance feedback."}],mistakes:{vi:["Dùng mã .9 không biến chứng dù bệnh án ghi rõ biến chứng.","Áp mức hưởng trên cả chi phí ngoài danh mục BHYT.","Thêm mã bệnh hoặc dịch vụ không có trong bệnh án để tăng thanh toán."],en:["Using the .9 no-complication code although the record states a complication.","Applying the benefit level to out-of-formulary costs.","Adding diagnoses or services not in the record to increase payment."]},career:[{vi:"Nhân viên mã hóa bệnh tật",en:"Clinical coder"},{vi:"Chuyên viên giám định & thanh toán BHYT",en:"Medical coding & claims specialist"},{vi:"Trưởng nhóm mã hóa / Kiểm soát hồ sơ thanh toán",en:"Coding lead / Claims audit lead"},{vi:"Trưởng bộ phận Bảo hiểm y tế và tài chính bệnh viện",en:"Head of health insurance & hospital revenue"}],glossary:[{term:"ICD-10",vi:"Bảng phân loại quốc tế bệnh tật lần thứ 10 của WHO dùng để mã hóa chẩn đoán.",en:"WHO's International Classification of Diseases, 10th revision, used to code diagnoses."},{term:"Bệnh chính",vi:"Tình trạng được xác định cuối đợt điều trị là nguyên nhân chính khiến người bệnh cần điều trị, thăm khám.",en:"The condition identified at the end of care as chiefly responsible for the need for treatment."},{term:"Upcoding",vi:"Nâng mã: mã hóa bệnh hoặc dịch vụ nặng hơn thực tế để được thanh toán cao hơn.",en:"Coding a more severe condition or service than actually occurred to get paid more."},{term:"Xuất toán",vi:"Phần chi phí bị cơ quan bảo hiểm từ chối thanh toán sau giám định.",en:"Costs the insurer refuses to pay after auditing a claim."},{term:"Cùng chi trả",vi:"Phần chi phí trong phạm vi BHYT mà người bệnh tự trả theo mức hưởng của thẻ.",en:"The share of covered costs the patient pays according to the card's benefit level."}],quiz:[{q:{vi:"Tổng chi phí 5.000.000 đồng, ngoài danh mục 600.000 đồng, mức hưởng 80%. BHYT chi trả bao nhiêu?",en:"Total cost 5,000,000 VND, out-of-formulary 600,000 VND, benefit level 80%. How much does the insurer pay?"},options:{vi:["3.520.000 đồng","4.000.000 đồng","4.400.000 đồng","880.000 đồng"],en:["3,520,000 VND","4,000,000 VND","4,400,000 VND","880,000 VND"]},answer:0,explain:{vi:"(5.000.000 - 600.000) x 80% = 4.400.000 x 0,8 = 3.520.000 đồng.",en:"(5,000,000 - 600,000) x 80% = 4,400,000 x 0.8 = 3,520,000 VND."}},{q:{vi:"Mã ICD-10 nào là viêm phổi, không đặc hiệu?",en:"Which ICD-10 code is pneumonia, unspecified?"},options:{vi:["J45.9","I10","N18.5","J18.9"],en:["J45.9","I10","N18.5","J18.9"]},answer:3,explain:{vi:"J18.9 là viêm phổi không đặc hiệu; J45.9 là hen, I10 là tăng huyết áp nguyên phát, N18.5 là bệnh thận mạn giai đoạn 5.",en:"J18.9 is pneumonia, unspecified; J45.9 is asthma, I10 essential hypertension and N18.5 CKD stage 5."}},{q:{vi:"Trưởng khoa yêu cầu thêm dịch vụ chưa thực hiện vào bảng kê để bù vượt trần. Bạn làm gì?",en:"A department head asks you to add services that were not performed to cover an overrun. What do you do?"},options:{vi:["Thêm vì là yêu cầu của trưởng khoa","Từ chối, mã hóa đúng bệnh án và báo cấp có thẩm quyền","Thêm một dịch vụ thay vì hai","Gửi hồ sơ nhưng ghi chú riêng"],en:["Add them because the head asked","Refuse, code from the record and escalate","Add one service instead of two","Submit with a private note"]},answer:1,explain:{vi:"Kê khống là trục lợi quỹ BHYT, có thể bị xử lý hành chính hoặc hình sự; phải từ chối và báo cáo.",en:"Phantom billing defrauds the insurance fund and can bring administrative or criminal penalties; refuse and report."}},{q:{vi:"Người bệnh đái tháo đường týp 2 dùng insulin. Điều nào đúng khi mã hóa?",en:"A type 2 diabetic patient uses insulin. Which coding statement is correct?"},options:{vi:["Chuyển sang nhóm E10 vì dùng insulin","Luôn dùng E11.9","Giữ nhóm E11, chọn ký tự thứ tư theo biến chứng","Không cần mã đái tháo đường"],en:["Switch to E10 because of insulin","Always use E11.9","Keep E11 and choose the fourth character by complication","No diabetes code is needed"]},answer:2,explain:{vi:"Týp bệnh do chẩn đoán xác định, không do thuốc điều trị; ký tự thứ tư phản ánh biến chứng.",en:"The type is set by diagnosis, not treatment; the fourth character reflects the complication."}}],tools_en:["Hospital information system (HIS)","ICD-10 lookup tool","Health insurance (BHYT) claims review system","Pre-submission XML data validation software","Microsoft Excel"]}}})})(window.KKR);
